import{_ as r,a0 as o,w as m,s as l,ao as p,I as n,a1 as i,A as a,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"在 Linux 下使用 RAID（一）：使用 mdadm 工具创建软件 RAID 0 （条带化） | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（一）：使用 mdadm 工具创建软件 RAID 0 （条带化） | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（一）：使用 mdadm 工具创建软件 RAID 0 （条带化） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（一）：使用 mdadm 工具创建软件 RAID 0 （条带化） | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 2 - Creating Software RAID0 (Stripe) on ‘Two Devices’ Using ‘mdadm’ Tool in Linux","title":"在 Linux 下使用 RAID（一）：使用 mdadm 工具创建软件 RAID 0 （条带化）","tag":"RAID","desc":""},"relativePath":"RAID/Part 2 - Creating Software RAID0 (Stripe) on ‘Two Devices’ Using ‘mdadm’ Tool in Linux.md","filePath":"[post].md"}'),c={name:"RAID/Part 2 - Creating Software RAID0 (Stripe) on ‘Two Devices’ Using ‘mdadm’ Tool in Linux.md"};function s(D,e,A,I,R,u){const d=o("Link");return m(),l("div",null,[e[14]||(e[14]=p('<h1 id="在-linux-下使用-raid-一-使用-mdadm-工具创建软件-raid-0-条带化" tabindex="-1">在 Linux 下使用 RAID（一）：使用 mdadm 工具创建软件 RAID 0 （条带化） <a class="header-anchor" href="#在-linux-下使用-raid-一-使用-mdadm-工具创建软件-raid-0-条带化" aria-label="Permalink to “在 Linux 下使用 RAID（一）：使用 mdadm 工具创建软件 RAID 0 （条带化）”">​</a></h1><p>RAID 即廉价磁盘冗余阵列，其高可用性和可靠性适用于大规模环境中，相比正常使用，数据更需要被保护。RAID 是一些磁盘的集合，是包含一个阵列的逻辑卷。驱动器可以组合起来成为一个阵列或称为（组的）集合。</p><p>创建 RAID 最少应使用2个连接到 RAID 控制器的磁盘组成，来构成逻辑卷，可以根据定义的 RAID 级别将更多的驱动器添加到一个阵列中。不使用物理硬件创建的 RAID 被称为软件 RAID。软件 RAID 也叫做穷人 RAID。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Raid0-in-Linux.jpg" alt="Setup RAID0 in Linux"></p><p><em>在 Linux 中创建 RAID0</em></p><p>使用 RAID 的主要目的是为了在发生单点故障时保存数据，如果我们使用单个磁盘来存储数据，如果它损坏了，那么就没有机会取回我们的数据了，为了防止数据丢失我们需要一个容错的方法。所以，我们可以使用多个磁盘组成 RAID 阵列。</p><h4 id="在-raid-0-中条带是什么" tabindex="-1">在 RAID 0 中条带是什么 <a class="header-anchor" href="#在-raid-0-中条带是什么" aria-label="Permalink to “在 RAID 0 中条带是什么”">​</a></h4><p>条带是通过将数据在同时分割到多个磁盘上。假设我们有两个磁盘，如果我们将数据保存到该逻辑卷上，它会将数据保存在两个磁盘上。使用 RAID 0 是为了获得更好的性能，但是如果驱动器中一个出现故障，我们将不能得到完整的数据。因此，使用 RAID 0 不是一种好的做法。唯一的解决办法就是安装有 RAID 0 逻辑卷的操作系统来提高重要文件的安全性。</p><ul><li>RAID 0 性能较高。</li><li>在 RAID 0 上，空间零浪费。</li><li>零容错（如果硬盘中的任何一个发生故障，无法取回数据）。</li><li>写和读性能都很好。</li></ul><h4 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h4><p>创建 RAID 0 允许的最小磁盘数目是2个，但你可以添加更多的磁盘，不过数目应该是2，4，6，8等的偶数。如果你有一个物理 RAID 卡并且有足够的端口，你可以添加更多磁盘。</p><p>在这里，我们没有使用硬件 RAID，此设置只需要软件 RAID。如果我们有一个物理硬件 RAID 卡，我们可以从它的功能界面访问它。有些主板默认内建 RAID 功能，还可以使用 Ctrl + I 键访问它的界面。</p><p>如果你是刚开始设置 RAID，请阅读我们前面的文章，我们已经介绍了一些关于 RAID 基本的概念。</p>',13)),n("ul",null,[n("li",null,[i(d,{href:"https://linux.cn/article-6085-1.html"},{default:a(()=>[...e[0]||(e[0]=[t("介绍 RAID 的级别和概念",-1)])]),_:1})])]),e[15]||(e[15]=p(`<p><strong>我的服务器设置</strong></p><pre><code>操作系统 :	CentOS 6.5 Final
IP 地址	 :	192.168.0.225
两块盘	 :	20 GB each
</code></pre><p>这是9篇系列教程的第2部分，在这部分，我们将看看如何能够在 Linux 上创建和使用 RAID 0（条带化），以名为 sdb 和 sdc 两个 20GB 的硬盘为例。</p><h3 id="第1步-更新系统和安装管理-raid-的-mdadm-软件" tabindex="-1">第1步：更新系统和安装管理 RAID 的 mdadm 软件 <a class="header-anchor" href="#第1步-更新系统和安装管理-raid-的-mdadm-软件" aria-label="Permalink to “第1步：更新系统和安装管理 RAID 的 mdadm 软件”">​</a></h3><p>1、 在 Linux 上设置 RAID 0 前，我们先更新一下系统，然后安装<code>mdadm</code> 包。mdadm 是一个小程序，这将使我们能够在Linux下配置和管理 RAID 设备。</p><pre><code># yum clean all &amp;&amp; yum update
# yum install mdadm -y
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/install-mdadm-in-linux.png" alt="install mdadm in linux"></p><p><em>安装 mdadm 工具</em></p><h3 id="第2步-确认连接了两个-20gb-的硬盘" tabindex="-1">第2步：确认连接了两个 20GB 的硬盘 <a class="header-anchor" href="#第2步-确认连接了两个-20gb-的硬盘" aria-label="Permalink to “第2步：确认连接了两个 20GB 的硬盘”">​</a></h3><p>2、 在创建 RAID 0 前，请务必确认两个硬盘能被检测到，使用下面的命令确认。</p><pre><code># ls -l /dev | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Hard-Drives.png" alt="Check Hard Drives in Linux"></p><p><em>检查硬盘</em></p><p>3、 一旦检测到新的硬盘驱动器，同时检查是否连接的驱动器已经被现有的 RAID 使用，使用下面的<code>mdadm</code> 命令来查看。</p><pre><code># mdadm --examine /dev/sd[b-c]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Drives-using-RAID.png" alt="Check RAID Devices in Linux"></p><p><em>检查 RAID 设备</em></p><p>从上面的输出我们可以看到，没有任何 RAID 使用 sdb 和 sdc 这两个驱动器。</p><h3 id="第3步-创建-raid-分区" tabindex="-1">第3步：创建 RAID 分区 <a class="header-anchor" href="#第3步-创建-raid-分区" aria-label="Permalink to “第3步：创建 RAID 分区”">​</a></h3><p>4、 现在用 sdb 和 sdc 创建 RAID 的分区，使用 fdisk 命令来创建。在这里，我将展示如何创建 sdb 驱动器上的分区。</p><pre><code># fdisk /dev/sdb
</code></pre><p>请按照以下说明创建分区。</p><ul><li>按<code>n</code> 创建新的分区。</li><li>然后按<code>P</code> 选择主分区。</li><li>接下来选择分区号为1。</li><li>只需按两次回车键选择默认值即可。</li><li>然后，按<code>P</code> 来显示创建好的分区。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-Partitions-in-Linux.png" alt="Create Partitions in Linux"></p><p><em>创建分区</em></p><p>请按照以下说明将分区创建为 Linux 的 RAID 类型。</p><ul><li>按<code>L</code>，列出所有可用的类型。</li><li>按<code>t</code> 去修改分区。</li><li>键入<code>fd</code> 设置为 Linux 的 RAID 类型，然后按回车确认。</li><li>然后再次使用<code>p</code>查看我们所做的更改。</li><li>使用<code>w</code>保存更改。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-RAID-Partitions.png" alt="Create RAID Partitions"></p><p><em>在 Linux 上创建 RAID 分区</em></p><p><strong>注</strong>: 请使用上述步骤同样在 sdc 驱动器上创建分区。</p><p>5、 创建分区后，验证这两个驱动器是否正确定义 RAID，使用下面的命令。</p><pre><code># mdadm --examine /dev/sd[b-c]
# mdadm --examine /dev/sd[b-c]1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Partitions.png" alt="Verify RAID Partitions"></p><p><em>验证 RAID 分区</em></p><h3 id="第4步-创建-raid-md-设备" tabindex="-1">第4步：创建 RAID md 设备 <a class="header-anchor" href="#第4步-创建-raid-md-设备" aria-label="Permalink to “第4步：创建 RAID md 设备”">​</a></h3><p>6、 现在使用以下命令创建 md 设备（即 /dev/md0），并选择 RAID 合适的级别。</p><pre><code># mdadm -C /dev/md0 -l raid0 -n 2 /dev/sd[b-c]1
# mdadm --create /dev/md0 --level=stripe --raid-devices=2 /dev/sd[b-c]1
</code></pre><ul><li>-C – 创建</li><li>-l – 级别</li><li>-n – RAID 设备数</li></ul><p>7、 一旦 md 设备已经建立，使用如下命令可以查看 RAID 级别，设备和阵列的使用状态。</p><pre><code># cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Level.png" alt="Verify RAID Level"></p><p><em>查看 RAID 级别</em></p><pre><code># mdadm -E /dev/sd[b-c]1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Device.png" alt="Verify RAID Device"></p><p><em>查看 RAID 设备</em></p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Array.png" alt="Verify RAID Array"></p><p><em>查看 RAID 阵列</em></p><h3 id="第5步-给-raid-设备创建文件系统" tabindex="-1">第5步：给 RAID 设备创建文件系统 <a class="header-anchor" href="#第5步-给-raid-设备创建文件系统" aria-label="Permalink to “第5步：给 RAID 设备创建文件系统”">​</a></h3><p>8、 将 RAID 设备 /dev/md0 创建为 ext4 文件系统，并挂载到 /mnt/raid0 下。</p><pre><code># mkfs.ext4 /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-ext4-Filesystem.png" alt="Create ext4 Filesystem in Linux"></p><p><em>创建 ext4 文件系统</em></p><p>9、 在 RAID 设备上创建好 ext4 文件系统后，现在创建一个挂载点（即 /mnt/raid0），并将设备 /dev/md0 挂载在它下。</p><pre><code># mkdir /mnt/raid0
# mount /dev/md0 /mnt/raid0/
</code></pre><p>10、下一步，使用 df 命令验证设备 /dev/md0 是否被挂载在 /mnt/raid0 下。</p><pre><code># df -h
</code></pre><p>11、 接下来，在挂载点 /mnt/raid0 下创建一个名为<code>tecmint.txt</code> 的文件，为创建的文件添加一些内容，并查看文件和目录的内容。</p><pre><code># touch /mnt/raid0/tecmint.txt
# echo &quot;Hi everyone how you doing ?&quot; &gt; /mnt/raid0/tecmint.txt
# cat /mnt/raid0/tecmint.txt
# ls -l /mnt/raid0/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-Mount-Device.png" alt="Verify Mount Device"></p><p><em>验证挂载的设备</em></p><p>12、 当你验证挂载点后，就可以将它添加到 /etc/fstab 文件中。</p><pre><code># vim /etc/fstab
</code></pre><p>添加以下条目，根据你的安装位置和使用文件系统的不同，自行做修改。</p><pre><code>/dev/md0                /mnt/raid0              ext4    deaults         0 0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Add-Device-to-Fstab.png" alt="Add Device to Fstab"></p><p><em>添加设备到 fstab 文件中</em></p><p>13、 使用 mount 命令的 <code>-a</code> 来检查 fstab 的条目是否有误。</p><pre><code># mount -av
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Errors-in-Fstab.png" alt="Check Errors in Fstab"></p><p><em>检查 fstab 文件是否有误</em></p><h3 id="第6步-保存-raid-配置" tabindex="-1">第6步：保存 RAID 配置 <a class="header-anchor" href="#第6步-保存-raid-配置" aria-label="Permalink to “第6步：保存 RAID 配置”">​</a></h3><p>14、 最后，保存 RAID 配置到一个文件中，以供将来使用。我们再次使用带有<code>-s</code> (scan) 和<code>-v</code> (verbose) 选项的 <code>mdadm</code> 命令，如图所示。</p><pre><code># mdadm -E -s -v &gt;&gt; /etc/mdadm.conf
# mdadm --detail --scan --verbose &gt;&gt; /etc/mdadm.conf  
# cat /etc/mdadm.conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Save-RAID-Configurations.png" alt="Save RAID Configurations"></p><p><em>保存 RAID 配置</em></p><p>就这样，我们在这里看到，如何通过使用两个硬盘配置具有条带化的 RAID 0 。在接下来的文章中，我们将看到如何设置 RAID 1。</p><hr>`,78)),n("p",null,[e[2]||(e[2]=t("via: ",-1)),i(d,{href:"http://www.tecmint.com/create-raid0-in-linux/"},{default:a(()=>[...e[1]||(e[1]=[t("http://www.tecmint.com/create-raid0-in-linux/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=t("作者：",-1)),i(d,{href:"http://www.tecmint.com/author/babinlonston/"},{default:a(()=>[...e[3]||(e[3]=[t("Babin Lonston",-1)])]),_:1}),e[7]||(e[7]=t(" 译者：",-1)),i(d,{href:"https://github.com/strugglingyouth"},{default:a(()=>[...e[4]||(e[4]=[t("strugglingyouth",-1)])]),_:1}),e[8]||(e[8]=t(" 校对：",-1)),i(d,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[11]||(e[11]=t("本文由 ",-1)),i(d,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原创翻译，",-1)),i(d,{href:"https://linux.cn/"},{default:a(()=>[...e[10]||(e[10]=[t("Linux中国",-1)])]),_:1}),e[13]||(e[13]=t(" 荣誉推出",-1))])])}const x=r(c,[["render",s]]);export{h as __pageData,x as default};
